<script setup lang="tsx">
import { WatchStopHandle } from "vue";
import { onBeforeUnmount, onMounted, ref, watch, computed } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import { GetHighlightKeyByJudgeLanguage, GetSubmitLanguages, IsJudgeLanguageValid, JudgeLanguage } from "@/apis/language.ts";
import {
  GetJudgeJobList,
  GetJudgeStatusStr,
  IsJudgeStatusRunning,
  JudgeStatus,
  GetJudgeStatusOptions,
  ParseJudgeJob,
  GetJudgeJobCode,
  GetJudgeStatusTheme,
  IsJudgeStatusValid,
} from "@/apis/judge.ts";
import { handleGotoContestProblem, handleGotoJudgeJob, handleGotoUsername } from "@/util/router.ts";
import { GetJudgeLanguageStr } from "@/apis/language.ts";
import { GetContestProblemIndexStr } from "@/apis/contest.ts";
import type { JudgeJob, JudgeJobView } from "@/types/judge.ts";
import { GetAvatarUrl } from "@/util/avatar.ts";
import { useUserStore } from "@/stores/user.ts";
import { AuthType } from "@/auth";
import { GetRemoteJudgeTypeOptions, GetRemoteJudgeTypeStr, RemoteJudgeType } from "@/apis/remote.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;
let refreshTimeout: ReturnType<typeof setTimeout>;

const codeShow = ref(false);
const showJudgeJob = ref<JudgeJobView | null>(null);

const isCodeLoading = ref(false);

let contestId = ref(-1);

const userStore = useUserStore();

let contestInserterId = -1;

const languageOptions = GetSubmitLanguages();
const judgeStatusOptions = GetJudgeStatusOptions();
const originOjOptions = GetRemoteJudgeTypeOptions();

const filterValue = ref<Record<string, any>>({});

const getFilterDescription = () => {
  const parts: string[] = [];
  const fv = filterValue.value;
  if (fv.originOj != undefined && fv.originOj !== "") {
    const opt = originOjOptions.find((o) => o.value === fv.originOj);
    parts.push("OJ：" + (opt?.label || fv.originOj));
  }
  if (fv.problemKey) {
    parts.push("题号：" + fv.problemKey);
  }
  if (fv.status != undefined && fv.status !== "") {
    const opt = judgeStatusOptions.find((o) => o.value === fv.status);
    parts.push("状态：" + (opt?.label || fv.status));
  }
  if (fv.code != undefined && fv.code !== "") {
    const opt = languageOptions.find((o) => o.value === fv.code);
    parts.push("语言：" + (opt?.label || fv.code));
  }
  if (fv.inserter) {
    parts.push("作者：" + fv.inserter);
  }
  return parts.join("；");
};

const filterRow = () => {
  const desc = getFilterDescription();
  if (!desc) return null;
  return (
    <t-space align="center">
      <span>{desc}</span>
      <t-button theme="primary" variant="text" onClick={onClearFilter}>
        清空筛选
      </t-button>
    </t-space>
  );
};

const onClearFilter = async () => {
  filterValue.value = {};
  await router.push({
    query: {
      ...route.query,
      page: 1,
      origin_oj: undefined,
      problem_key: undefined,
      language: undefined,
      status: undefined,
      username: undefined,
    },
  });
};

const getOriginOjParam = () => {
  const val = filterValue.value.originOj;
  if (val != undefined && val !== "") {
    return GetRemoteJudgeTypeStr(val as RemoteJudgeType);
  }
  return "";
};

const listColumns = computed(() => {
  const allColumns = [
  {
    title: "ID",
    colKey: "id",
    cell: (_: any, data: any) => {
      let clickFunction = null;
      if (
        (!data.row.private ||
          (userStore.isLogin() &&
            (data.row.inserter == userStore.getUserId || contestInserterId == userStore.getUserId || userStore.hasAuth(AuthType.ManageJudge)))) &&
        IsJudgeStatusValid(data.row.status) &&
        IsJudgeLanguageValid(data.row.language)
      ) {
        clickFunction = () => {
          handleGotoJudgeJob(data.row.id, contestId.value);
        };
      }
      return (
        <t-button variant="text" onClick={clickFunction}>
          {data.row.id}
        </t-button>
      );
    },
  },
  {
    title: "OJ",
    colKey: "originOj",
    width: 100,
    filter: {
      type: "single",
      list: originOjOptions,
      showConfirmAndReset: true,
    },
    cell: (_: any, data: any) => {
      return <t-tag variant="light">{data.row.originOj || "DidaOJ"}</t-tag>;
    },
  },
  {
    title: "问题",
    colKey: "problemKey",
    filter: {
      type: "input",
      showConfirmAndReset: true,
      props: { placeholder: "请输入完整题号" },
    },
    cell: (_: any, data: any) => {
      if (contestId.value) {
        return (
          <t-button variant="text" onClick={() => handleGotoContestProblem(contestId.value, data.row.contestProblemIndex)}>
            {GetContestProblemIndexStr(data.row.contestProblemIndex)}
          </t-button>
        );
      }
      return (
        <t-button variant="text" onClick={() => handleGotoProblem(data.row.problemKey)}>
          {data.row.problemKey}
        </t-button>
      );
    },
  },
  {
    title: "状态",
    colKey: "status",
    align: "center",
    filter: {
      type: "single",
      list: judgeStatusOptions,
      showConfirmAndReset: true,
    },
    cell: (_: any, data: any) => {
      let clickFunction = null;
      if (
        (!data.row.private ||
          (userStore.isLogin() &&
            (data.row.inserter == userStore.getUserId || contestInserterId == userStore.getUserId || userStore.hasAuth(AuthType.ManageJudge)))) &&
        IsJudgeStatusValid(data.row.status) &&
        IsJudgeLanguageValid(data.row.language)
      ) {
        clickFunction = () => {
          handleGotoJudgeJob(data.row.id, contestId.value);
        };
      }
      const status = data.row.status as JudgeStatus;
      const statusStr = GetJudgeStatusStr(status);
      let disabled = !IsJudgeStatusValid(status);
      const theme = GetJudgeStatusTheme(status);
      let finalElements = [];
      if (IsJudgeStatusRunning(status)) {
        finalElements.push(<t-loading text={data.row.state} size="small" class="dida-status-loading"></t-loading>);
      }
      finalElements.push(<span>{statusStr}</span>);
      return (
        <t-button theme={theme} variant="outline" onClick={clickFunction} disabled={disabled}>
          {finalElements}
        </t-button>
      );
    },
  },
  {
    title: "分数",
    colKey: "score",
  },
  {
    title: "时间",
    colKey: "time",
  },
  {
    title: "内存",
    colKey: "memory",
  },
  {
    title: "代码",
    colKey: "code",
    filter: {
      type: "single",
      list: languageOptions,
      showConfirmAndReset: true,
    },
    cell: (_: any, data: any) => {
      let buttonText = GetJudgeLanguageStr(data.row.language);
      const languageValid = IsJudgeLanguageValid(data.row.language);
      if (languageValid && data.row.codeLength > 0) {
        buttonText = buttonText + " / " + data.row.codeLength;
      }
      let disabled =
        !languageValid ||
        (data.row.private &&
          !userStore.hasAuth(AuthType.ManageJudge) &&
          (!userStore.isLogin() || (data.row.inserter != userStore.getUserId && contestInserterId != userStore.getUserId)));
      return (
        <t-button theme="default" onClick={() => handleShowCode(data.row)} disabled={disabled}>
          {buttonText}
        </t-button>
      );
    },
  },
  {
    title: "作者",
    colKey: "inserter",
    filter: {
      type: "input",
      showConfirmAndReset: true,
      props: { placeholder: "仅支持输入完整用户名" },
    },
    cell: (_: any, data: any) => {
      const avatarUrl = GetAvatarUrl(data.row.inserterUsername, data.row.inserterEmail);
      return (
        <t-space>
          <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
          <t-button variant="text" onClick={() => handleGotoUsername(router, data.row.inserterUsername)}>
            {data.row.inserterNickname}
          </t-button>
        </t-space>
      );
    },
  },
  {
    title: "提交时间",
    colKey: "insertTime",
  },
  ];
  // 移动端隐藏次要列：分数、时间、内存、代码
  if (isMobile.value) {
    return allColumns.filter((col) => !["score", "time", "memory", "code"].includes(col.colKey));
  }
  return allColumns;
});

const dataLoading = ref(false);

let currentPage = 1;
let currentPageSize = 20;

const pagination = ref({
  current: currentPage,
  pageSize: currentPageSize,
  defaultCurrent: currentPage,
  defaultPageSize: currentPageSize,
  total: 200,
  pageSizeOptions: [20, 100],
  showPageSize: false,
  totalContent: (h: any, value: any) => {
    return (
      <div>
        <t-tag>目前仅支持获取前10页数据</t-tag>
      </div>
    );
  },
});

const judgeJobViews = ref<JudgeJobView[]>();

const handleShowCode = async (jobView: JudgeJobView) => {
  isCodeLoading.value = true;
  codeShow.value = true;
  try {
    showJudgeJob.value = jobView;

    const res = await GetJudgeJobCode(Number(showJudgeJob.value.id));
    if (res.code === 0) {
      const response = res.data;
      const language = GetHighlightKeyByJudgeLanguage(response.language);

      showJudgeJob.value.code = `\`\`\`${language}\n${response.code}\n\`\`\``;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } finally {
    isCodeLoading.value = false;
  }
};

const handleGotoProblem = (id: string) => {
  if (!id) {
    return;
  }
  router.push({ path: "/problem/" + id });
};

const onFilterChange = async (filters: Record<string, any>) => {
  const cleaned: Record<string, any> = {};
  for (const [key, val] of Object.entries(filters)) {
    if (val !== "" && val !== undefined && val !== null) {
      cleaned[key] = val;
    }
  }
  filterValue.value = cleaned;
  await router.push({
    query: {
      ...route.query,
      page: 1,
      origin_oj: cleaned.originOj ?? undefined,
      problem_key: cleaned.problemKey || undefined,
      language: cleaned.code ?? undefined,
      status: cleaned.status ?? undefined,
      username: cleaned.inserter || undefined,
    },
  });
};

const fetchData = async (paginationInfo: { current: number; pageSize: number }, needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  let needRefresh = false;
  try {
    const { current, pageSize } = paginationInfo;
    const res = await GetJudgeJobList(
      contestId.value,
      filterValue.value.problemKey || "",
      filterValue.value.inserter || "",
      filterValue.value.code != undefined && filterValue.value.code !== ""
        ? Number(filterValue.value.code)
        : undefined,
      filterValue.value.status != undefined && filterValue.value.status !== ""
        ? Number(filterValue.value.status)
        : undefined,
      getOriginOjParam(),
      current,
      pageSize
    );
    judgeJobViews.value = [];
    if (res.code === 0) {
      if (!res.data.has_auth) {
        ShowTextTipsInfo(globalProperties, "您目前没有权限查看评测记录");
        if (contestId.value) {
          await router.push({ name: "contest-detail", params: { contestId: contestId.value } });
        } else {
          await router.push({ name: "judge-list" });
        }
        return;
      }

      contestInserterId = -1;
      if (res.data.contest) {
        contestInserterId = res.data.contest.inserter;
      }

      if (res.data.list && res.data.list.length > 0) {
        const responseList = res.data.list as JudgeJob[];
        responseList.forEach((item) => {
          const result = ParseJudgeJob(item);
          judgeJobViews.value?.push(result);
          if (IsJudgeStatusRunning(item.status)) {
            needRefresh = true;
          }
        });
      } else {
        ShowTextTipsInfo(globalProperties, "未找到记录");
      }
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
    if (needRefresh && viewActive) {
      refreshTimeout = setTimeout(() => {
        fetchData({ current: currentPage, pageSize: currentPageSize }, false);
      }, 5000);
    }
  }
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  await router.push({
    query: { ...route.query, page: pageInfo.current },
  });
};

onMounted(async () => {
  viewActive = true;

  watchHandle = watch(
    () => route.query,
    (newQuery) => {
      if (Array.isArray(route.params.contestId)) {
        contestId.value = Number(route.params.contestId[0]);
      } else {
        contestId.value = Number(route.params.contestId);
      }

      const newFilterValue: Record<string, any> = {};
      const problemKey = (newQuery.problem_key as string) || "";
      const username = (newQuery.username as string) || "";
      if (problemKey) {
        newFilterValue.problemKey = problemKey;
      }
      if (username) {
        newFilterValue.inserter = username;
      }
      if (newQuery.language != undefined) {
        newFilterValue.code = Number(newQuery.language as string) as JudgeLanguage;
      }
      if (newQuery.status != undefined) {
        newFilterValue.status = Number(newQuery.status as string) as JudgeStatus;
      }
      if (newQuery.origin_oj != undefined) {
        newFilterValue.originOj = Number(newQuery.origin_oj as string) as RemoteJudgeType;
      }
      filterValue.value = newFilterValue;

      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      currentPage = queryPage;
      currentPageSize = queryPageSize;
      if (!pagination.value.pageSizeOptions.includes(currentPageSize)) {
        currentPageSize = pagination.value.defaultPageSize;
      }
      pagination.value = { ...pagination.value, current: currentPage, pageSize: currentPageSize };
      fetchData({ current: currentPage, pageSize: currentPageSize }, true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  viewActive = false;

  if (watchHandle) {
    watchHandle();
  }

  clearTimeout(refreshTimeout);
});
</script>

<template>
  <t-card style="margin: 10px">
    <div style="overflow-x: auto; width: 100%">
      <t-table
        :data="judgeJobViews"
        :columns="listColumns"
        row-key="id"
        vertical-align="top"
        :hover="true"
        :pagination="pagination"
        :loading="dataLoading"
        :filter-value="filterValue"
        :filter-row="filterRow"
        @page-change="onPageChange"
        @filter-change="onFilterChange"
        table-layout="auto"
      />
    </div>
  </t-card>

  <t-dialog v-model:visible="codeShow" :width="isMobile ? '90%' : '800px'" :cancel-btn="null" :close-btn="false" @confirm="codeShow = false">
    <template #header>
      <t-link
        @click="
          () => {
            handleGotoJudgeJob(showJudgeJob?.id, contestId);
          }
        "
      >
        {{ showJudgeJob?.id + " - " + GetJudgeLanguageStr(showJudgeJob?.language) }}
      </t-link>
    </template>
    <t-loading :loading="isCodeLoading">
      <md-preview :model-value="showJudgeJob?.code" :code-foldable="false" style="min-height: 100px"></md-preview>
    </t-loading>
  </t-dialog>
</template>

<style scoped>
:deep(.dida-status-loading) {
  margin-right: 5px;
}
</style>
